/**
 * Core persisted/user entities: transcripts, dictionary entries, voice commands.
 * These shapes are shared between the engine, IPC surface, and UI.
 */

/** A completed dictation turn, as stored in the local SQLite history. */
export interface TranscriptItem {
  /** Stable unique id (UUID v4, generated by the engine). */
  id: string;
  /** Unix epoch milliseconds. */
  createdAt: number;
  /** App the text was injected into (best-effort window title / process name). */
  app?: string;
  /** Raw STT output before any correction or polish. */
  rawText: string;
  /** Final text after dictionary correction + polish (or offline cleanup). */
  finalText?: string;
  /** Duration of the dictation turn in milliseconds. */
  durationMs?: number;
  /** Whisper model id used, e.g. `"whisper-small"`. */
  sttModel?: string;
  /** Polish model id used, e.g. `"qwen2.5-3b-instruct-q4"` (absent when none). */
  polishModel?: string;
  /** Absolute path of the saved WAV when audio saving is on. */
  audioPath?: string;
  /**
   * Their `History.transcriptCommand` — how the dictation was triggered:
   * `ptt` (hold/toggle hotkey), `popo` (hands-free toggle), `command`
   * (voice command), `lens` (command-mode). Their PTT/POPO distinction maps
   * to our hold vs toggle modes.
   */
  triggerSource?: "ptt" | "popo" | "command" | "lens";
}

/** A personal-dictionary term used for fuzzy post-STT correction. */
export interface DictionaryEntry {
  id: string;
  /** Canonical spelling, e.g. `"OpenWispr"`. May contain multiple words. */
  term: string;
  /** How the word sounds — reserved for future STT biasing / hints. */
  pronunciation?: string;
  /** Free-form usage hint injected into the polish prompt. */
  hint?: string;
}

/** Actions a spoken voice command can trigger. */
export type VoiceCommandAction = "undo" | "insert" | "replace";

/** A spoken phrase mapped to an action (e.g. "scratch that" → undo). */
export interface VoiceCommand {
  id: string;
  /** Spoken phrase, lowercased at match time. */
  phrase: string;
  action: VoiceCommandAction;
  /** Action payload: text to insert (insert) or replacement text (replace). */
  payload?: string;
}

/** Query options for `history/list`. */
export interface HistoryQuery {
  /** Case-insensitive substring match over raw and final text. */
  query?: string;
  /** Max items to return (most recent first). Default 50, max 500. */
  limit?: number;
}
